drop policy if exists kleenest_fleet_driver_scorecards_manage on public.fleet_driver_scorecards; create policy fleet_driver_scorecards_observe on public.fleet_driver_scorecards for select to authenticated using (public.fleet_observe_access(business_id));
drop policy if exists kleenest_fleet_maintenance_manage on public.fleet_maintenance_records; create policy fleet_maintenance_observe on public.fleet_maintenance_records for select to authenticated using (public.fleet_observe_access(business_id));
drop policy if exists kleenest_fleet_vehicle_metrics_manage on public.fleet_vehicle_daily_metrics; create policy fleet_vehicle_metrics_observe on public.fleet_vehicle_daily_metrics for select to authenticated using (public.fleet_observe_access(business_id));
drop policy if exists fleet_route_updates_scoped_read on public.fleet_route_updates; create policy fleet_route_updates_scoped_read on public.fleet_route_updates for select to authenticated using (exists(select 1 from public.fleet_routes r where r.id=fleet_route_updates.route_id and public.fleet_observe_access(r.business_id)));
drop policy if exists fleet_metric_definitions_admin_or_fleet_read on public.fleet_metric_definitions; create policy fleet_metric_definitions_observe on public.fleet_metric_definitions for select to authenticated using (public.fleet_observe_access(business_id));
drop policy if exists fleet_metric_assignments_admin_or_fleet_read on public.fleet_metric_assignments; create policy fleet_metric_assignments_observe on public.fleet_metric_assignments for select to authenticated using (exists(select 1 from public.fleet_metric_definitions md where md.id=fleet_metric_assignments.metric_definition_id and public.fleet_observe_access(md.business_id)));
drop policy if exists fleet_performance_events_scoped_read on public.fleet_performance_events; create policy fleet_performance_events_scoped_read on public.fleet_performance_events for select to authenticated using ((fleet_vehicle_id is not null and exists(select 1 from public.fleet_vehicles fv where fv.id=fleet_performance_events.fleet_vehicle_id and public.fleet_observe_access(fv.business_id))) or (route_id is not null and exists(select 1 from public.fleet_routes r where r.id=fleet_performance_events.route_id and public.fleet_observe_access(r.business_id))));
